/** The generated island pages (scripts/island-pages/build.cjs, issue 05 slice C). */
declare module "lh-island-pages" {
	export const KATEX_VERSION: string;
	export const MERMAID_VERSION: string;
	/** The math page: HTML shell with the KaTeX CSS and fonts. */
	export const MATH_HTML: string;
	/** The math page script, for `injectedJavaScript`. */
	export const MATH_SCRIPT: string;
	/** The Mermaid page: HTML shell. */
	export const MERMAID_HTML: string;
	/** mermaid.min.js and the Mermaid page script, for `injectedJavaScript`. */
	export const MERMAID_SCRIPT: string;
	/** The math page for the full-screen viewer (pinch zoom up to 4). */
	export const MATH_VIEWER_HTML: string;
	/** The Mermaid page for the full-screen viewer (pinch zoom up to 4). */
	export const MERMAID_VIEWER_HTML: string;
}
